class Solution {
    public int minRunesToAdd(int n, int[] crystals, int[] flowFrom, int[] flowTo) {
        List<Integer>[] adj = new ArrayList[n];
        List<Integer>[] revAdj = new ArrayList[n];
        for (int i = 0; i < n; ++i) {
            adj[i] = new ArrayList<>();
            revAdj[i] = new ArrayList<>();
        }
        for (int i = 0; i < flowFrom.length; ++i) {
            adj[flowFrom[i]].add(flowTo[i]);
            revAdj[flowTo[i]].add(flowFrom[i]);
        }

        boolean[] visited = new boolean[n];
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                Deque<int[]> st = new ArrayDeque<>();
                st.push(new int[]{i, 0});
                visited[i] = true;
                while (!st.isEmpty()) {
                    int[] top = st.peek();
                    int u = top[0], idx = top[1];
                    if (idx < adj[u].size()) {
                        top[1]++;
                        int v = adj[u].get(idx);
                        if (!visited[v]) {
                            visited[v] = true;
                            st.push(new int[]{v, 0});
                        }
                    } else {
                        order.add(u);
                        st.pop();
                    }
                }
            }
        }

        int[] compId = new int[n];
        Arrays.fill(compId, -1);
        int cCount = 0;
        for (int i = n - 1; i >= 0; --i) {
            int u = order.get(i);
            if (compId[u] == -1) {
                Deque<Integer> st = new ArrayDeque<>();
                st.push(u);
                compId[u] = cCount;
                while (!st.isEmpty()) {
                    int curr = st.pop();
                    for (int v : revAdj[curr]) {
                        if (compId[v] == -1) {
                            compId[v] = cCount;
                            st.push(v);
                        }
                    }
                }
                cCount++;
            }
        }

        List<Integer>[] dagAdj = new ArrayList[cCount];
        for (int i = 0; i < cCount; ++i) dagAdj[i] = new ArrayList<>();
        int[] inDegree = new int[cCount];
        for (int i = 0; i < flowFrom.length; ++i) {
            int cu = compId[flowFrom[i]], cv = compId[flowTo[i]];
            if (cu != cv) {
                dagAdj[cu].add(cv);
                inDegree[cv]++;
            }
        }

        boolean[] reachable = new boolean[cCount];
        Deque<Integer> q = new ArrayDeque<>();
        for (int c : crystals) {
            int cid = compId[c];
            if (!reachable[cid]) {
                reachable[cid] = true;
                q.push(cid);
            }
        }
        while (!q.isEmpty()) {
            int cu = q.pop();
            for (int cv : dagAdj[cu]) {
                if (!reachable[cv]) {
                    reachable[cv] = true;
                    q.push(cv);
                }
            }
        }

        int ans = 0;
        for (int c = 0; c < cCount; ++c) {
            if (!reachable[c] && inDegree[c] == 0) ans++;
        }
        return ans;
    }
}

var minRunesToAdd = function(n, crystals, flowFrom, flowTo) {
    const adj = Array.from({ length: n }, () => []);
    const revAdj = Array.from({ length: n }, () => []);
    for (let i = 0; i < flowFrom.length; i++) {
        adj[flowFrom[i]].push(flowTo[i]);
        revAdj[flowTo[i]].push(flowFrom[i]);
    }

    const visited = new Uint8Array(n);
    const order = [];
    for (let i = 0; i < n; i++) {
        if (!visited[i]) {
            const st = [[i, 0]];
            visited[i] = 1;
            while (st.length > 0) {
                const top = st[st.length - 1];
                const u = top[0];
                if (top[1] < adj[u].length) {
                    const v = adj[u][top[1]++];
                    if (!visited[v]) {
                        visited[v] = 1;
                        st.push([v, 0]);
                    }
                } else {
                    order.push(u);
                    st.pop();
                }
            }
        }
    }

    const compId = new Int32Array(n).fill(-1);
    let cCount = 0;
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        if (compId[u] === -1) {
            const st = [u];
            compId[u] = cCount;
            while (st.length > 0) {
                const curr = st.pop();
                for (const v of revAdj[curr]) {
                    if (compId[v] === -1) {
                        compId[v] = cCount;
                        st.push(v);
                    }
                }
            }
            cCount++;
        }
    }

    const dagAdj = Array.from({ length: cCount }, () => []);
    const inDegree = new Int32Array(cCount);
    for (let i = 0; i < flowFrom.length; i++) {
        const cu = compId[flowFrom[i]], cv = compId[flowTo[i]];
        if (cu !== cv) {
            dagAdj[cu].push(cv);
            inDegree[cv]++;
        }
    }

    const reachable = new Uint8Array(cCount);
    const q = [];
    for (const c of crystals) {
        const cid = compId[c];
        if (!reachable[cid]) {
            reachable[cid] = 1;
            q.push(cid);
        }
    }
    while (q.length > 0) {
        const cu = q.pop();
        for (const cv of dagAdj[cu]) {
            if (!reachable[cv]) {
                reachable[cv] = 1;
                q.push(cv);
            }
        }
    }

    let ans = 0;
    for (let c = 0; c < cCount; c++) {
        if (!reachable[c] && inDegree[c] === 0) ans++;
    }
    return ans;
